    <section data-report-panel="expiry" class="report-panel hidden rounded-2xl border bg-white p-5"><form method="GET" class="mb-4 flex flex-wrap items-end gap-3"><input type="hidden" name="tab" value="expiry"><label class="text-sm font-semibold">Sắp hết hạn trong (tháng)<input type="number" name="months" min="1" max="60" value="{{ $months }}" class="mt-1 block rounded-lg border px-3 py-2.5"></label><button class="rounded-lg bg-slate-900 px-4 py-2.5 font-bold text-white">Xem</button></form>@forelse($expiringAssets as $asset)<p class="border-b p-2">{{ $asset->code }} — {{ $asset->name }} — Hết hạn: {{ $asset->expiry_date?->format('d/m/Y') }}</p>@empty<p class="text-slate-500">Không có vật tư sắp hết hạn.</p>@endforelse</section>
