    <section data-report-panel="logs" class="report-panel hidden overflow-x-auto rounded-2xl border bg-white p-5"><h2 class="mb-3 text-lg font-bold">Nhật ký cập nhật vật tư</h2><table class="w-full min-w-[900px] text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-2">Thời gian</th><th class="p-2">Thao tác</th><th class="p-2">Đối tượng</th><th class="p-2">Người thực hiện</th><th class="p-2">Chi tiết</th></tr></thead><tbody>@forelse($auditLogs as $log)<tr class="border-t"><td class="p-2">{{ $log->created_at?->format('d/m/Y H:i') }}</td><td class="p-2">{{ ['INCREASE'=>'Tăng','DECREASE'=>'Giảm','ADJUST'=>'Điều chỉnh','TRANSFER'=>'Điều động','RECALL'=>'Thu hồi'][$log->action] ?? $log->action }}</td><td class="p-2">{{ $log->entity_type }} #{{ $log->entity_id }}</td><td class="p-2">{{ $log->user?->name }}</td><td class="p-2">{{ collect($log->details ?? [])->filter(fn($v)=>is_scalar($v))->map(fn($v)=>$v)->implode(' — ') }}</td></tr>@empty<tr><td colspan="5" class="p-6 text-center text-slate-500">Chưa có nhật ký cập nhật.</td></tr>@endforelse</tbody></table></section>
    <script>document.querySelectorAll('.report-tab').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.report-tab').forEach(x=>x.classList.toggle('bg-slate-900',x===tab));document.querySelectorAll('.report-tab').forEach(x=>x.classList.toggle('text-white',x===tab));document.querySelectorAll('.report-panel').forEach(x=>x.classList.toggle('hidden',x.dataset.reportPanel!==tab.dataset.reportTab))}));</script>
